  // GPU compute particle system for GoSX Scene3D.
  // WGSL compute shaders for particle simulation + JS CPU fallback.
  // Shared IIFE scope: sceneNumber, sceneColorRGBA available from scene-math.js.

  // --- WGSL Compute Shader Source ---

  var SCENE_COMPUTE_PARTICLE_SOURCE = [
    "struct Particle {",
    "    posX: f32, posY: f32, posZ: f32,",
    "    velX: f32, velY: f32, velZ: f32,",
    "    age: f32,",
    "    lifetime: f32,",
    "};",
    "",
    "struct RenderVertex {",
    "    posX: f32, posY: f32, posZ: f32,",
    "    size: f32,",
    "    r: f32, g: f32, b: f32, a: f32,",
    "};",
    "",
    "struct SimParams {",
    "    deltaTime: f32,",
    "    totalTime: f32,",
    "    count: u32,",
    "    _pad0: u32,",
    "    emitterKind: u32,",
    "    emitterX: f32, emitterY: f32, emitterZ: f32,",
    "    emitterRadius: f32,",
    "    emitterRate: f32,",
    "    emitterLifetime: f32,",
    "    emitterOnce: u32,",
    "    emitterArms: u32,",
    "    emitterWind: f32,",
    "    emitterScatter: f32,",
    "    emitterRotX: f32, emitterRotY: f32, emitterRotZ: f32,",
    "    _pad2: u32,",
    "    sizeStart: f32, sizeEnd: f32,",
    "    colorStartR: f32, colorStartG: f32, colorStartB: f32,",
    "    colorEndR: f32, colorEndG: f32, colorEndB: f32,",
    "    opacityStart: f32, opacityEnd: f32,",
    "    forceCount: u32,",
    "    bounds: f32,",
    "};",
    "",
    "struct Force {",
    "    kind: u32,",
    "    strength: f32,",
    "    dirX: f32, dirY: f32, dirZ: f32,",
    "    frequency: f32,",
    "    _pad0: f32, _pad1: f32,",
    "};",
    "",
    "@group(0) @binding(0) var<storage, read_write> particles: array<Particle>;",
    "@group(0) @binding(1) var<storage, read_write> renderData: array<RenderVertex>;",
    "@group(0) @binding(2) var<uniform> params: SimParams;",
    "@group(0) @binding(3) var<storage, read> forces: array<Force>;",
    "",
    "fn hash(seed: u32) -> f32 {",
    "    var s = seed;",
    "    s = s ^ (s >> 16u);",
    "    s = s * 0x45d9f3bu;",
    "    s = s ^ (s >> 16u);",
    "    s = s * 0x45d9f3bu;",
    "    s = s ^ (s >> 16u);",
    "    return f32(s) / f32(0xffffffffu);",
    "}",
    "",
    "fn hash2(a: u32, b: u32) -> f32 {",
    "    return hash(a * 1597334677u + b * 3812015801u);",
    "}",
    "",
    "fn emitPoint(index: u32, p: SimParams) -> Particle {",
    "    var out: Particle;",
    "    out.posX = 0.0;",
    "    out.posY = 0.0;",
    "    out.posZ = 0.0;",
    "    out.velX = (hash2(index, 0u) - 0.5) * 0.1;",
    "    out.velY = (hash2(index, 1u) - 0.5) * 0.1;",
    "    out.velZ = (hash2(index, 2u) - 0.5) * 0.1;",
    "    out.age = 0.0;",
    "    out.lifetime = particleLifetime(index, p);",
    "    return out;",
    "}",
    "",
    "fn emitSphere(index: u32, p: SimParams) -> Particle {",
    "    var out: Particle;",
    "    let theta = hash2(index, 10u) * 6.283185;",
    "    let phi = acos(2.0 * hash2(index, 11u) - 1.0);",
    "    let r = p.emitterRadius * pow(hash2(index, 12u), 0.333);",
    "    out.posX = r * sin(phi) * cos(theta);",
    "    out.posY = r * cos(phi);",
    "    out.posZ = r * sin(phi) * sin(theta);",
    "    out.velX = 0.0; out.velY = 0.0; out.velZ = 0.0;",
    "    out.age = 0.0;",
    "    out.lifetime = particleLifetime(index, p);",
    "    return out;",
    "}",
    "",
    "fn emitDisc(index: u32, p: SimParams) -> Particle {",
    "    var out: Particle;",
    "    let angle = hash2(index, 20u) * 6.283185;",
    "    let r = p.emitterRadius * sqrt(hash2(index, 21u));",
    "    out.posX = r * cos(angle);",
    "    out.posY = 0.0;",
    "    out.posZ = r * sin(angle);",
    "    out.velX = 0.0; out.velY = 0.0; out.velZ = 0.0;",
    "    out.age = 0.0;",
    "    out.lifetime = particleLifetime(index, p);",
    "    return out;",
    "}",
    "",
    "fn rotateEulerZYX(lx: f32, ly: f32, lz: f32, rx: f32, ry: f32, rz: f32) -> vec3<f32> {",
    "    let cx = cos(rx); let sx = sin(rx);",
    "    let cy = cos(ry); let sy = sin(ry);",
    "    let cz = cos(rz); let sz = sin(rz);",
    "    return vec3<f32>(",
    "        lx*(cy*cz) + ly*(sx*sy*cz - cx*sz) + lz*(cx*sy*cz + sx*sz),",
    "        lx*(cy*sz) + ly*(sx*sy*sz + cx*cz) + lz*(cx*sy*sz - sx*cz),",
    "        lx*(-sy)   + ly*(sx*cy)             + lz*(cx*cy)",
    "    );",
    "}",
    "",
    "fn emitSpiral(index: u32, p: SimParams) -> Particle {",
    "    var out: Particle;",
    "    let radius = hash2(index, 30u) * p.emitterRadius;",
    "    let arm = index % p.emitterArms;",
    "    let armAngle = f32(arm) * 3.14159265 / f32(max(p.emitterArms / 2u, 1u));",
    "    let spiralAngle = armAngle + (radius / p.emitterRadius) * p.emitterWind;",
    "    let scatter = (hash2(index, 31u) - 0.5) * radius * p.emitterScatter;",
    "    let lx = cos(spiralAngle) * radius + scatter;",
    "    let ly = (hash2(index, 32u) - 0.5) * p.emitterRadius * 0.05;",
    "    let lz = sin(spiralAngle) * radius + (hash2(index, 33u) - 0.5) * radius * p.emitterScatter;",
    "    out.posX = lx;",
    "    out.posY = ly;",
    "    out.posZ = lz;",
    "    out.velX = 0.0; out.velY = 0.0; out.velZ = 0.0;",
    "    out.age = 0.0;",
    "    out.lifetime = particleLifetime(index, p);",
    "    return out;",
    "}",
    "",
    "fn emitParticle(index: u32, p: SimParams) -> Particle {",
    "    switch (p.emitterKind) {",
    "        case 1u: { return emitSphere(index, p); }",
    "        case 2u: { return emitDisc(index, p); }",
    "        case 3u: { return emitSpiral(index, p); }",
    "        default: { return emitPoint(index, p); }",
    "    }",
    "}",
    "",
    "fn particleLifetime(index: u32, p: SimParams) -> f32 {",
    "    let base = max(p.emitterLifetime, 0.001);",
    "    return base * (0.64 + hash2(index, 44u) * 0.92);",
    "}",
    "",
    "fn particleDelay(index: u32, p: SimParams) -> f32 {",
    "    let base = max(p.emitterLifetime, 0.001);",
    "    if (p.emitterOnce != 0u) {",
    "        return pow(hash2(index, 47u), 1.8) * max(0.08, base * 0.12);",
    "    }",
    "    var window = base;",
    "    if (p.emitterRate > 0.001) {",
    "        window = max(base * 0.35, f32(p.count) / p.emitterRate);",
    "    }",
    "    let wave = floor(hash2(index, 46u) * 5.0) / 5.0;",
    "    let jitter = pow(hash2(index, 47u), 2.2) * 0.18;",
    "    return min(window, (wave + jitter) * window);",
    "}",
    "",
    "fn particleEnvelope(t: f32) -> f32 {",
    "    let born = smoothstep(0.0, 0.11, t);",
    "    let spent = 1.0 - smoothstep(0.66, 1.0, t);",
    "    return born * spent;",
    "}",
    "",
    "fn makeDormant(index: u32, p: SimParams) -> Particle {",
    "    var out: Particle;",
    "    out.posX = 0.0; out.posY = 0.0; out.posZ = 0.0;",
    "    out.velX = 0.0; out.velY = 0.0; out.velZ = 0.0;",
    "    out.age = -particleDelay(index, p);",
    "    out.lifetime = particleLifetime(index, p);",
    "    return out;",
    "}",
    "",
    "fn makeFinished(index: u32) -> Particle {",
    "    var out: Particle;",
    "    out.posX = 0.0; out.posY = 0.0; out.posZ = 0.0;",
    "    out.velX = 0.0; out.velY = 0.0; out.velZ = 0.0;",
    "    out.age = -1.0;",
    "    out.lifetime = -1.0;",
    "    return out;",
    "}",
    "",
    "fn writeDormant(index: u32, p: Particle) {",
    "    particles[index] = p;",
    "    var rv: RenderVertex;",
    "    rv.posX = 0.0; rv.posY = 0.0; rv.posZ = 0.0;",
    "    rv.size = 0.0;",
    "    rv.r = 1.0; rv.g = 1.0; rv.b = 1.0; rv.a = 0.0;",
    "    renderData[index] = rv;",
    "}",
    "",
    "fn applyGravity(part: Particle, f: Force, dt: f32) -> vec3f {",
    "    return vec3f(f.dirX, f.dirY, f.dirZ) * f.strength * dt;",
    "}",
    "",
    "fn applyWind(part: Particle, f: Force, dt: f32) -> vec3f {",
    "    return vec3f(f.dirX, f.dirY, f.dirZ) * f.strength * dt;",
    "}",
    "",
    "fn applyTurbulence(part: Particle, f: Force, dt: f32, time: f32) -> vec3f {",
    "    let freq = f.frequency;",
    "    let nx = sin(part.posX * freq + time * 1.3) * cos(part.posZ * freq + time * 0.7);",
    "    let ny = sin(part.posY * freq + time * 0.9) * cos(part.posX * freq + time * 1.1);",
    "    let nz = sin(part.posZ * freq + time * 1.7) * cos(part.posY * freq + time * 0.5);",
    "    return vec3f(nx, ny, nz) * f.strength * dt;",
    "}",
    "",
    "fn applyOrbit(part: Particle, f: Force, dt: f32) -> vec3f {",
    "    let dx = part.posX;",
    "    let dz = part.posZ;",
    "    let dist = max(sqrt(dx * dx + dz * dz), 0.001);",
    "    return vec3f(-dz / dist, 0.0, dx / dist) * f.strength * dt;",
    "}",
    "",
    "fn applyDrag(part: Particle, f: Force, dt: f32) -> vec3f {",
    "    return vec3f(-part.velX, -part.velY, -part.velZ) * f.strength * dt;",
    "}",
    "",
    "fn applyRadial(part: Particle, f: Force, dt: f32) -> vec3f {",
    "    var dir = vec3f(part.posX, part.posY, part.posZ);",
    "    let bias = vec3f(f.dirX, f.dirY, f.dirZ);",
    "    let biasLen = length(bias);",
    "    if (biasLen > 0.001) {",
    "        dir = dir + normalize(bias) * max(length(dir), 1.0) * 0.35;",
    "    }",
    "    let dist = max(length(dir), 0.001);",
    "    return (dir / dist) * f.strength * dt;",
    "}",
    "",
    "@compute @workgroup_size(64)",
    "fn simulate(@builtin(global_invocation_id) id: vec3u) {",
    "    let i = id.x;",
    "    if (i >= params.count) { return; }",
    "",
    "    var p = particles[i];",
    "",
    "    if (p.age < 0.0) {",
    "        if (params.emitterOnce != 0u && p.lifetime < -0.5) {",
    "            writeDormant(i, p);",
    "            return;",
    "        }",
    "        if (p.lifetime <= 0.0) {",
    "            p = emitParticle(i, params);",
    "        } else {",
    "            p.age += params.deltaTime;",
    "            if (p.age < 0.0) {",
    "                writeDormant(i, p);",
    "                return;",
    "            }",
    "            p = emitParticle(i, params);",
    "        }",
    "    }",
    "",
    "    p.age += params.deltaTime;",
    "",
    "    if (p.lifetime > 0.0 && p.age >= p.lifetime) {",
    "        if (params.emitterOnce != 0u) {",
    "            p = makeFinished(i);",
    "            writeDormant(i, p);",
    "            return;",
    "        }",
    "        p = makeDormant(i, params);",
    "        p.age += params.deltaTime;",
    "        if (p.age < 0.0) {",
    "            writeDormant(i, p);",
    "            return;",
    "        }",
    "        p = emitParticle(i, params);",
    "    }",
    "",
    "    for (var fi = 0u; fi < params.forceCount; fi++) {",
    "        let f = forces[fi];",
    "        switch (f.kind) {",
    "            case 0u: { let dv = applyGravity(p, f, params.deltaTime); p.velX += dv.x; p.velY += dv.y; p.velZ += dv.z; }",
    "            case 1u: { let dv = applyWind(p, f, params.deltaTime); p.velX += dv.x; p.velY += dv.y; p.velZ += dv.z; }",
    "            case 2u: { let dv = applyTurbulence(p, f, params.deltaTime, params.totalTime); p.velX += dv.x; p.velY += dv.y; p.velZ += dv.z; }",
    "            case 3u: { let dv = applyOrbit(p, f, params.deltaTime); p.velX += dv.x; p.velY += dv.y; p.velZ += dv.z; }",
    "            case 4u: { let dv = applyDrag(p, f, params.deltaTime); p.velX += dv.x; p.velY += dv.y; p.velZ += dv.z; }",
    "            case 5u: { let dv = applyRadial(p, f, params.deltaTime); p.velX += dv.x; p.velY += dv.y; p.velZ += dv.z; }",
    "            default: {}",
    "        }",
    "    }",
    "",
    "    p.posX += p.velX * params.deltaTime;",
    "    p.posY += p.velY * params.deltaTime;",
    "    p.posZ += p.velZ * params.deltaTime;",
    "",
    "    if (params.emitterOnce != 0u && params.bounds > 0.0 && length(vec3<f32>(p.posX, p.posY, p.posZ)) > params.bounds) {",
    "        p = makeFinished(i);",
    "        writeDormant(i, p);",
    "        return;",
    "    }",
    "",
    "    particles[i] = p;",
    "",
    "    let t = clamp(select(p.age / p.lifetime, 0.0, p.lifetime <= 0.0), 0.0, 1.0);",
    "    var rv: RenderVertex;",
    "    rv.posX = p.posX;",
    "    rv.posY = p.posY;",
    "    rv.posZ = p.posZ;",
    "    rv.size = mix(params.sizeStart, params.sizeEnd, t);",
    "    rv.r = mix(params.colorStartR, params.colorEndR, t);",
    "    rv.g = mix(params.colorStartG, params.colorEndG, t);",
    "    rv.b = mix(params.colorStartB, params.colorEndB, t);",
    "    rv.a = mix(params.opacityStart, params.opacityEnd, t) * particleEnvelope(t);",
    "    renderData[i] = rv;",
    "}",
  ].join("\n");

  var sceneParticleForceBuiltins = { gravity: 0, wind: 1, turbulence: 2, orbit: 3, drag: 4, radial: 5, eject: 5, outward: 5 };
  var sceneParticleForceAliases = Object.create(null);
  var sceneParticleForceHandlers = Object.create(null);
  var sceneParticleForceRegistryVersion = 0;

  function sceneParticleForceKindKey(value) {
    var key = typeof value === "string" ? value.trim().toLowerCase() : "";
    return key && /^[a-z][a-z0-9_-]*$/.test(key) ? key : "";
  }

  function sceneParticleForceKindCode(kind) {
    var key = sceneParticleForceKindKey(kind);
    if (Object.prototype.hasOwnProperty.call(sceneParticleForceBuiltins, key)) {
      return sceneParticleForceBuiltins[key];
    }
    if (Object.prototype.hasOwnProperty.call(sceneParticleForceAliases, key)) {
      return sceneParticleForceAliases[key];
    }
    return 0;
  }

  function registerSceneParticleForceKind(kind, targetKind) {
    var key = sceneParticleForceKindKey(kind);
    var target = sceneParticleForceKindKey(targetKind);
    if (!key) {
      return false;
    }
    var code;
    if (Object.prototype.hasOwnProperty.call(sceneParticleForceBuiltins, target)) {
      code = sceneParticleForceBuiltins[target];
    } else if (Object.prototype.hasOwnProperty.call(sceneParticleForceAliases, target)) {
      code = sceneParticleForceAliases[target];
    } else {
      return false;
    }
    sceneParticleForceAliases[key] = code;
    sceneParticleForceRegistryVersion += 1;
    return true;
  }

  function registerSceneParticleForce(kind, force) {
    var key = sceneParticleForceKindKey(kind);
    if (!key) {
      return false;
    }
    if (typeof force === "function") {
      sceneParticleForceHandlers[key] = force;
      sceneParticleForceRegistryVersion += 1;
      return true;
    }
    if (force && typeof force === "object") {
      var handler = typeof force.apply === "function" ? force.apply : (typeof force.update === "function" ? force.update : null);
      var aliasRegistered = false;
      if (typeof force.kind === "string") {
        aliasRegistered = registerSceneParticleForceKind(key, force.kind);
      }
      if (typeof force.kind === "string" && !aliasRegistered) {
        return false;
      }
      if (handler) {
        sceneParticleForceHandlers[key] = handler;
        sceneParticleForceRegistryVersion += 1;
        return true;
      }
      if (aliasRegistered) {
        return true;
      }
    }
    return false;
  }

  function unregisterSceneParticleForce(kind) {
    var key = sceneParticleForceKindKey(kind);
    var removed = false;
    if (Object.prototype.hasOwnProperty.call(sceneParticleForceAliases, key)) {
      delete sceneParticleForceAliases[key];
      removed = true;
    }
    if (Object.prototype.hasOwnProperty.call(sceneParticleForceHandlers, key)) {
      delete sceneParticleForceHandlers[key];
      removed = true;
    }
    if (removed) {
      sceneParticleForceRegistryVersion += 1;
    }
    return removed;
  }

  function listSceneParticleForces() {
    var keys = Object.keys(sceneParticleForceBuiltins)
      .concat(Object.keys(sceneParticleForceAliases))
      .concat(Object.keys(sceneParticleForceHandlers));
    return Array.from(new Set(keys)).sort().map(function(kind) {
      return {
        kind: kind,
        builtin: Object.prototype.hasOwnProperty.call(sceneParticleForceBuiltins, kind),
        alias: Object.prototype.hasOwnProperty.call(sceneParticleForceAliases, kind),
        handler: Object.prototype.hasOwnProperty.call(sceneParticleForceHandlers, kind),
      };
    });
  }

  function sceneParticleForceHandler(kind) {
    var key = sceneParticleForceKindKey(kind);
    return key && sceneParticleForceHandlers[key] || null;
  }

  function sceneApplyParticleForceHandler(handler, context) {
    var result = handler(context);
    if (!result) {
      return context.velocity;
    }
    if (Array.isArray(result) || (result && typeof result.length === "number")) {
      context.velocity.x += sceneNumber(result[0], 0);
      context.velocity.y += sceneNumber(result[1], 0);
      context.velocity.z += sceneNumber(result[2], 0);
      return context.velocity;
    }
    var nextVelocity = result.velocity && typeof result.velocity === "object" ? result.velocity : null;
    if (nextVelocity) {
      context.velocity.x = sceneNumber(nextVelocity.x, context.velocity.x);
      context.velocity.y = sceneNumber(nextVelocity.y, context.velocity.y);
      context.velocity.z = sceneNumber(nextVelocity.z, context.velocity.z);
      return context.velocity;
    }
    context.velocity.x += sceneNumber(Object.prototype.hasOwnProperty.call(result, "x") ? result.x : result.vx, 0);
    context.velocity.y += sceneNumber(Object.prototype.hasOwnProperty.call(result, "y") ? result.y : result.vy, 0);
    context.velocity.z += sceneNumber(Object.prototype.hasOwnProperty.call(result, "z") ? result.z : result.vz, 0);
    return context.velocity;
  }

  // --- SimParams Upload Helper ---

  function sceneComputeUploadSimParams(device, buffer, entry, deltaTime, totalTime) {
    var emitter = entry.emitter || {};
    var material = entry.material || {};
    var forces = entry.forces || [];

    var kindMap = { point: 0, sphere: 1, disc: 2, spiral: 3 };
    var emitterKind = kindMap[emitter.kind] || 0;

    var colorStart = sceneColorRGBA(material.color || "#ffffff", [1, 1, 1, 1]);
    var colorEnd = sceneColorRGBA(material.colorEnd || material.color || "#ffffff", [1, 1, 1, 1]);

    var buf = new ArrayBuffer(256);
    var view = new DataView(buf);
    var offset = 0;

    // SimParams layout (must match WGSL struct alignment):
    view.setFloat32(offset, deltaTime, true); offset += 4;            // deltaTime
    view.setFloat32(offset, totalTime, true); offset += 4;            // totalTime
    view.setUint32(offset, entry.count, true); offset += 4;           // count
    view.setUint32(offset, 0, true); offset += 4;                     // _pad0

    view.setUint32(offset, emitterKind, true); offset += 4;           // emitterKind
    view.setFloat32(offset, sceneNumber(emitter.x, 0), true); offset += 4;
    view.setFloat32(offset, sceneNumber(emitter.y, 0), true); offset += 4;
    view.setFloat32(offset, sceneNumber(emitter.z, 0), true); offset += 4;
    view.setFloat32(offset, sceneNumber(emitter.radius, 0), true); offset += 4;
    view.setFloat32(offset, sceneNumber(emitter.rate, 0), true); offset += 4;
    view.setFloat32(offset, sceneNumber(emitter.lifetime, 0), true); offset += 4;
    view.setUint32(offset, emitter.once === true ? 1 : 0, true); offset += 4;

    view.setUint32(offset, sceneNumber(emitter.arms, 2), true); offset += 4;
    view.setFloat32(offset, sceneNumber(emitter.wind, 0), true); offset += 4;
    view.setFloat32(offset, sceneNumber(emitter.scatter, 0), true); offset += 4;
    view.setFloat32(offset, sceneNumber(emitter.rotationX, 0), true); offset += 4;
    view.setFloat32(offset, sceneNumber(emitter.rotationY, 0), true); offset += 4;
    view.setFloat32(offset, sceneNumber(emitter.rotationZ, 0), true); offset += 4;
    view.setUint32(offset, 0, true); offset += 4;                     // _pad2

    // Material interpolation
    view.setFloat32(offset, sceneNumber(material.size, 1), true); offset += 4;
    view.setFloat32(offset, sceneNumber(material.sizeEnd, material.size || 1), true); offset += 4;
    view.setFloat32(offset, colorStart[0], true); offset += 4;
    view.setFloat32(offset, colorStart[1], true); offset += 4;
    view.setFloat32(offset, colorStart[2], true); offset += 4;
    view.setFloat32(offset, colorEnd[0], true); offset += 4;
    view.setFloat32(offset, colorEnd[1], true); offset += 4;
    view.setFloat32(offset, colorEnd[2], true); offset += 4;
    view.setFloat32(offset, sceneNumber(material.opacity, 1), true); offset += 4;
    view.setFloat32(offset, sceneNumber(material.opacityEnd, material.opacity || 1), true); offset += 4;

    // Force count
    view.setUint32(offset, forces.length, true); offset += 4;
    view.setFloat32(offset, sceneNumber(entry.bounds, 0), true); offset += 4;

    device.queue.writeBuffer(buffer, 0, buf, 0, 256);
  }

  function sceneComputeUploadForces(device, buffer, forces) {
    var byteLen = Math.max(32, forces.length * 32);
    var buf = new ArrayBuffer(byteLen);
    var view = new DataView(buf);

    for (var i = 0; i < forces.length; i++) {
      var f = forces[i];
      var off = i * 32;
      view.setUint32(off, sceneParticleForceKindCode(f && f.kind), true);
      view.setFloat32(off + 4, sceneNumber(f.strength, 0), true);
      view.setFloat32(off + 8, sceneNumber(f.x, 0), true);
      view.setFloat32(off + 12, sceneNumber(f.y, 0), true);
      view.setFloat32(off + 16, sceneNumber(f.z, 0), true);
      view.setFloat32(off + 20, sceneNumber(f.frequency, 1), true);
      // 8 bytes padding (offsets 24-31)
    }

    device.queue.writeBuffer(buffer, 0, buf);
  }

  // --- GPU Compute Particle System ---

  function sceneComputeIsErrorScopeLifecycleMessage(message) {
    var text = String(message || "").toLowerCase();
    return text.indexOf("poperrorscope") >= 0 && text.indexOf("instance dropped") >= 0;
  }

  function sceneComputePopErrorScope(scopedDevice) {
    if (!scopedDevice || typeof scopedDevice.popErrorScope !== "function") {
      return Promise.resolve(null);
    }
    try {
      return scopedDevice.popErrorScope().then(function(scopeErr) {
        return scopeErr || null;
      }).catch(function(error) {
        var message = error && error.message ? error.message : String(error);
        if (sceneComputeIsErrorScopeLifecycleMessage(message)) return null;
        return error || new Error(message);
      });
    } catch (error) {
      var message = error && error.message ? error.message : String(error);
      if (sceneComputeIsErrorScopeLifecycleMessage(message)) {
        return Promise.resolve(null);
      }
      return Promise.resolve(error || new Error(message));
    }
  }

  function createSceneComputeParticleSystem(device, entry) {
    var count = entry.count || 0;
    if (count <= 0) return null;

    // Particle state: 8 floats per particle (pos xyz, vel xyz, age, lifetime).
    var particleBuffer = device.createBuffer({
      size: count * 32,
      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
    });

    // Render output: 8 floats per vertex (pos xyz, size, rgba).
    var renderBuffer = device.createBuffer({
      size: count * 32,
      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.VERTEX,
    });

    // Uniform buffer for simulation parameters.
    var paramsBuffer = device.createBuffer({
      size: 256,
      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
    });

    // Storage buffer for force descriptors.
    var forceCount = (entry.forces || []).length;
    var forceBuffer = device.createBuffer({
      size: Math.max(32, forceCount * 32),
      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
    });

    // Initialize all particle ages to -1 (triggers first-frame emission in shader).
    var initData = new Float32Array(count * 8);
    for (var i = 0; i < count; i++) {
      initData[i * 8 + 6] = -1.0;
    }
    device.queue.writeBuffer(particleBuffer, 0, initData);

    // Upload static force data.
    sceneComputeUploadForces(device, forceBuffer, entry.forces || []);

    // Compile compute pipeline (async).
    var computePipeline = null;
    var bindGroup = null;
    var ready = false;
    var disposed = false;
    // Per-system cache: true if the payload kernel failed and we fell back to builtin.
    var payloadKernelFailed = false;

    var bindGroupLayout = device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: GPUShaderStage.COMPUTE, buffer: { type: "storage" } },
        { binding: 1, visibility: GPUShaderStage.COMPUTE, buffer: { type: "storage" } },
        { binding: 2, visibility: GPUShaderStage.COMPUTE, buffer: { type: "uniform" } },
        { binding: 3, visibility: GPUShaderStage.COMPUTE, buffer: { type: "read-only-storage" } },
      ],
    });

    var pipelineLayout = device.createPipelineLayout({
      bindGroupLayouts: [bindGroupLayout],
    });

    function markComputePipelineReady(pipeline) {
      if (disposed) return;
      computePipeline = pipeline;
      bindGroup = device.createBindGroup({
        layout: bindGroupLayout,
        entries: [
          { binding: 0, resource: { buffer: particleBuffer } },
          { binding: 1, resource: { buffer: renderBuffer } },
          { binding: 2, resource: { buffer: paramsBuffer } },
          { binding: 3, resource: { buffer: forceBuffer } },
        ],
      });
      ready = true;
    }

    function buildPipelineFromSource(wgslSource, entryPoint) {
      var mod = device.createShaderModule({ code: wgslSource });
      return {
        layout: pipelineLayout,
        compute: { module: mod, entryPoint: entryPoint },
      };
    }

    // Determine pipeline source: use payload kernel when provided, falling back
    // to the builtin on async validation failure. IMPORTANT: per the WebGPU
    // spec, createShaderModule() never throws on invalid WGSL, and
    // createComputePipeline() does not throw on shader-validation failure either
    // — errors surface asynchronously via error scopes / getCompilationInfo and
    // the returned pipeline is internally invalid. We therefore validate with
    // createComputePipelineAsync (which rejects on failure) and a surrounding
    // pushErrorScope("validation") / popErrorScope() belt-and-braces check.
    // The system stays not-ready (isReady() === false) while validation is
    // pending; frames silently skip the compute pass via the guard at update().
    var payloadWGSL = (typeof entry.computeWGSL === "string" && entry.computeWGSL.trim()) ? entry.computeWGSL : null;
    var payloadEntry = (typeof entry.computeEntry === "string" && entry.computeEntry.trim()) ? entry.computeEntry : "simulate";
    var systemID = (entry && typeof entry.id === "string") ? entry.id : "";

    function buildBuiltinPipeline() {
      if (disposed) return;
      var scopedDevice = device;
      try {
        scopedDevice.pushErrorScope("validation");
      } catch (_err) {
        return;
      }
      scopedDevice.createComputePipelineAsync(buildPipelineFromSource(SCENE_COMPUTE_PARTICLE_SOURCE, "simulate")).then(function(pipeline) {
        return sceneComputePopErrorScope(scopedDevice).then(function(scopeErr) {
          if (disposed) return;
          if (scopeErr) {
            console.warn("[gosx] Compute particle builtin pipeline validation error:", scopeErr);
          } else {
            markComputePipelineReady(pipeline);
          }
        });
      }).catch(function(err) {
        return sceneComputePopErrorScope(scopedDevice).then(function() {
          if (disposed) return;
          console.warn("[gosx] Compute particle builtin pipeline creation failed:", err);
        });
      });
    }

    function tryBuildPayloadPipelineAsync() {
      if (disposed) return;
      var scopedDevice = device;
      try {
        scopedDevice.pushErrorScope("validation");
      } catch (_err) {
        buildBuiltinPipeline();
        return;
      }
      scopedDevice.createComputePipelineAsync(buildPipelineFromSource(payloadWGSL, payloadEntry)).then(function(pipeline) {
        return sceneComputePopErrorScope(scopedDevice).then(function(scopeErr) {
          if (disposed) return;
          if (scopeErr) {
            // Scope captured a validation error even though the async pipeline
            // call resolved — treat as failure (belt-and-braces).
            if (!payloadKernelFailed) {
              payloadKernelFailed = true;
              console.warn("[gosx] Compute particle payload kernel failed for system '" + systemID + "'; falling back to builtin.");
            }
            buildBuiltinPipeline();
          } else {
            markComputePipelineReady(pipeline);
          }
        });
      }).catch(function() {
        return sceneComputePopErrorScope(scopedDevice).then(function() {
          if (disposed) return;
          if (!payloadKernelFailed) {
            payloadKernelFailed = true;
            console.warn("[gosx] Compute particle payload kernel failed for system '" + systemID + "'; falling back to builtin.");
          }
          buildBuiltinPipeline();
        });
      });
    }

    if (payloadWGSL) {
      tryBuildPayloadPipelineAsync();
    } else {
      buildBuiltinPipeline();
    }

    return {
      count: count,
      renderBuffer: renderBuffer,
      entry: entry,
      isReady: function() {
        return ready;
      },

      update: function(device, encoder, deltaTime, totalTime) {
        if (!ready) return;

        sceneComputeUploadSimParams(device, paramsBuffer, entry, deltaTime, totalTime);

        var pass = encoder.beginComputePass();
        pass.setPipeline(computePipeline);
        pass.setBindGroup(0, bindGroup);
        pass.dispatchWorkgroups(Math.ceil(count / 64));
        pass.end();
      },

      dispose: function() {
        disposed = true;
        particleBuffer.destroy();
        renderBuffer.destroy();
        paramsBuffer.destroy();
        forceBuffer.destroy();
        computePipeline = null;
        bindGroup = null;
        ready = false;
      },
    };
  }

  // --- CPU Fallback Particle System ---
  // Mirrors the WGSL compute shader logic in plain JS for WebGL2 environments.
  // Produces positions/sizes/colors arrays compatible with drawPointsEntries.

  function createSceneCPUParticleSystem(entry) {
    var count = Math.min(entry.count || 0, 10000);
    if (count <= 0) return null;

    // Particle state: same 8-float layout as GPU (posXYZ, velXYZ, age, lifetime).
    var particles = new Float32Array(count * 8);

    // Output arrays for the Points renderer.
    var positions = new Float32Array(count * 3);
    var sizes = new Float32Array(count);
    var colors = new Float32Array(count * 3);
    var opacities = new Float32Array(count);

    // Initialize ages to -1 (uninitialized marker).
    for (var i = 0; i < count; i++) {
      particles[i * 8 + 6] = -1.0;
    }

    // Deterministic hash RNG (same as WGSL).
    function hash(seed) {
      var s = seed >>> 0;
      s = s ^ (s >>> 16);
      s = Math.imul(s, 0x45d9f3b) >>> 0;
      s = s ^ (s >>> 16);
      s = Math.imul(s, 0x45d9f3b) >>> 0;
      s = s ^ (s >>> 16);
      return (s >>> 0) / 0xffffffff;
    }

    function hash2(a, b) {
      return hash(Math.imul(a >>> 0, 1597334677) + Math.imul(b >>> 0, 3812015801));
    }

    // Emitter kind map.
    var kindMap = { point: 0, sphere: 1, disc: 2, spiral: 3 };

    function currentEmitterConfig() {
      var emitter = entry && entry.emitter && typeof entry.emitter === "object" ? entry.emitter : {};
      // NOTE: emit in LOCAL space (origin-centered, no rotation). The compute
      // particle render bridge sets x/y/z/rotation/spin on the rendered Points
      // entry so the model matrix applies position + rotation + spin at draw time.
      // This matches how static Points work and gives us free galaxy spin.
      return {
        kind: kindMap[emitter.kind] || 0,
        x: 0,
        y: 0,
        z: 0,
        radius: sceneNumber(emitter.radius, 0),
        lifetime: sceneNumber(emitter.lifetime, 0),
        arms: Math.max(1, Math.floor(sceneNumber(emitter.arms, 2))),
        wind: sceneNumber(emitter.wind, 0),
        scatter: sceneNumber(emitter.scatter, 0),
        bounds: sceneNumber(entry && entry.bounds, 0),
        once: emitter.once === true,
      };
    }

    function currentMaterialConfig() {
      var material = entry && entry.material && typeof entry.material === "object" ? entry.material : {};
      return {
        colorStart: sceneColorRGBA(material.color || "#ffffff", [1, 1, 1, 1]),
        colorEnd: sceneColorRGBA(material.colorEnd || material.color || "#ffffff", [1, 1, 1, 1]),
        sizeStart: sceneNumber(material.size, 1),
        sizeEnd: sceneNumber(material.sizeEnd, material.size || 1),
        opacityStart: sceneNumber(material.opacity, 1),
        opacityEnd: sceneNumber(material.opacityEnd, material.opacity || 1),
      };
    }

    function currentForces() {
      return Array.isArray(entry && entry.forces) ? entry.forces : [];
    }

    function particleLifetime(index, emitterConfig) {
      var base = Math.max(sceneNumber(emitterConfig.lifetime, 0), 0.001);
      return base * (0.64 + hash2(index, 44) * 0.92);
    }

    function particleDelay(index, emitterConfig) {
      var base = Math.max(sceneNumber(emitterConfig.lifetime, 0), 0.001);
      if (emitterConfig.once) {
        return Math.pow(hash2(index, 47), 1.8) * Math.max(0.08, base * 0.12);
      }
      var rate = sceneNumber(entry && entry.emitter && entry.emitter.rate, 0);
      var windowSeconds = base;
      if (rate > 0.001) {
        windowSeconds = Math.max(base * 0.35, count / rate);
      }
      var wave = Math.floor(hash2(index, 46) * 5) / 5;
      var jitter = Math.pow(hash2(index, 47), 2.2) * 0.18;
      return Math.min(windowSeconds, (wave + jitter) * windowSeconds);
    }

    function smoothstep(edge0, edge1, x) {
      var t = Math.min(1, Math.max(0, (x - edge0) / (edge1 - edge0)));
      return t * t * (3 - 2 * t);
    }

    function particleEnvelope(t) {
      return smoothstep(0, 0.11, t) * (1 - smoothstep(0.66, 1, t));
    }

    function makeDormant(index, base, emitterConfig) {
      base[0] = 0; base[1] = 0; base[2] = 0;
      base[3] = 0; base[4] = 0; base[5] = 0;
      base[6] = -particleDelay(index, emitterConfig);
      base[7] = particleLifetime(index, emitterConfig);
    }

    function makeFinished(base) {
      base[0] = 0; base[1] = 0; base[2] = 0;
      base[3] = 0; base[4] = 0; base[5] = 0;
      base[6] = -1;
      base[7] = -1;
    }

    function writeDormantOutput(index) {
      var pbase = index * 3;
      positions[pbase] = 0;
      positions[pbase + 1] = 0;
      positions[pbase + 2] = 0;
      sizes[index] = 0;
      colors[pbase] = 1;
      colors[pbase + 1] = 1;
      colors[pbase + 2] = 1;
      opacities[index] = 0;
    }

    function emitParticle(index, base, emitterConfig) {
      // All emitters produce LOCAL coordinates (origin-centered). The render
      // pipeline applies the emitter's world position, rotation, and spin via
      // the model matrix on the Points entry.
      switch (emitterConfig.kind) {
        case 1: { // sphere
          var theta = hash2(index, 10) * 6.283185;
          var phi = Math.acos(2.0 * hash2(index, 11) - 1.0);
          var r = emitterConfig.radius * Math.pow(hash2(index, 12), 0.333);
          base[0] = r * Math.sin(phi) * Math.cos(theta);
          base[1] = r * Math.cos(phi);
          base[2] = r * Math.sin(phi) * Math.sin(theta);
          base[3] = 0; base[4] = 0; base[5] = 0;
          break;
        }
        case 2: { // disc
          var angle = hash2(index, 20) * 6.283185;
          var dr = emitterConfig.radius * Math.sqrt(hash2(index, 21));
          base[0] = dr * Math.cos(angle);
          base[1] = 0;
          base[2] = dr * Math.sin(angle);
          base[3] = 0; base[4] = 0; base[5] = 0;
          break;
        }
        case 3: { // spiral (local space)
          var radius = hash2(index, 30) * emitterConfig.radius;
          var arm = index % emitterConfig.arms;
          var armAngle = arm * 3.14159265 / Math.max(emitterConfig.arms / 2, 1);
          var spiralAngle = armAngle + (radius / Math.max(emitterConfig.radius, 0.001)) * emitterConfig.wind;
          var scatter = (hash2(index, 31) - 0.5) * radius * emitterConfig.scatter;
          base[0] = Math.cos(spiralAngle) * radius + scatter;
          base[1] = (hash2(index, 32) - 0.5) * emitterConfig.radius * 0.05;
          base[2] = Math.sin(spiralAngle) * radius + (hash2(index, 33) - 0.5) * radius * emitterConfig.scatter;
          base[3] = 0; base[4] = 0; base[5] = 0;
          break;
        }
        default: { // point
          base[0] = 0;
          base[1] = 0;
          base[2] = 0;
          base[3] = (hash2(index, 0) - 0.5) * 0.1;
          base[4] = (hash2(index, 1) - 0.5) * 0.1;
          base[5] = (hash2(index, 2) - 0.5) * 0.1;
          break;
        }
      }
      base[6] = 0.0;              // age
      base[7] = particleLifetime(index, emitterConfig);   // lifetime
    }

    return {
      count: count,
      positions: positions,
      sizes: sizes,
      colors: colors,
      opacities: opacities,
      entry: entry,

      update: function(deltaTime, totalTime) {
        var emitterConfig = currentEmitterConfig();
        var materialConfig = currentMaterialConfig();
        var forces = currentForces();
        var customForceContext = null;
        for (var i = 0; i < count; i++) {
          var base = i * 8;

          // Read particle state.
          var posX = particles[base];
          var posY = particles[base + 1];
          var posZ = particles[base + 2];
          var velX = particles[base + 3];
          var velY = particles[base + 4];
          var velZ = particles[base + 5];
          var age = particles[base + 6];
          var lifetime = particles[base + 7];

          // Initialize on first frame.
          if (age < 0) {
            if (emitterConfig.once && lifetime < -0.5) {
              writeDormantOutput(i);
              continue;
            }
            if (lifetime <= 0) {
              emitParticle(i, particles.subarray(base, base + 8), emitterConfig);
            } else {
              particles[base + 6] += deltaTime;
              if (particles[base + 6] < 0) {
                writeDormantOutput(i);
                continue;
              }
              emitParticle(i, particles.subarray(base, base + 8), emitterConfig);
            }
            posX = particles[base];
            posY = particles[base + 1];
            posZ = particles[base + 2];
            velX = particles[base + 3];
            velY = particles[base + 4];
            velZ = particles[base + 5];
            age = particles[base + 6];
            lifetime = particles[base + 7];
          }

          // Age.
          age += deltaTime;

          // Respawn dead particles.
          if (lifetime > 0 && age >= lifetime) {
            if (emitterConfig.once) {
              makeFinished(particles.subarray(base, base + 8));
              writeDormantOutput(i);
              continue;
            }
            makeDormant(i, particles.subarray(base, base + 8), emitterConfig);
            particles[base + 6] += deltaTime;
            if (particles[base + 6] < 0) {
              writeDormantOutput(i);
              continue;
            }
            emitParticle(i, particles.subarray(base, base + 8), emitterConfig);
            posX = particles[base];
            posY = particles[base + 1];
            posZ = particles[base + 2];
            velX = particles[base + 3];
            velY = particles[base + 4];
            velZ = particles[base + 5];
            age = particles[base + 6];
            lifetime = particles[base + 7];
          }

          // Apply forces.
          for (var fi = 0; fi < forces.length; fi++) {
            var f = forces[fi];
            var handler = sceneParticleForceHandler(f && f.kind);
            if (handler) {
              if (!customForceContext) {
                customForceContext = {
                  index: 0,
                  deltaTime: 0,
                  totalTime: 0,
                  age: 0,
                  lifetime: 0,
                  force: null,
                  position: { x: 0, y: 0, z: 0 },
                  velocity: { x: 0, y: 0, z: 0 },
                };
              }
              customForceContext.index = i;
              customForceContext.deltaTime = deltaTime;
              customForceContext.totalTime = totalTime;
              customForceContext.age = age;
              customForceContext.lifetime = lifetime;
              customForceContext.force = f;
              customForceContext.position.x = posX;
              customForceContext.position.y = posY;
              customForceContext.position.z = posZ;
              customForceContext.velocity.x = velX;
              customForceContext.velocity.y = velY;
              customForceContext.velocity.z = velZ;
              var customVelocity = sceneApplyParticleForceHandler(handler, customForceContext);
              velX = customVelocity.x;
              velY = customVelocity.y;
              velZ = customVelocity.z;
              continue;
            }
            var fKind = sceneParticleForceKindCode(f && f.kind);
            var str = sceneNumber(f.strength, 0);
            var fx = sceneNumber(f.x, 0);
            var fy = sceneNumber(f.y, 0);
            var fz = sceneNumber(f.z, 0);
            var freq = sceneNumber(f.frequency, 1);

            switch (fKind) {
              case 0: { // gravity
                velX += fx * str * deltaTime;
                velY += fy * str * deltaTime;
                velZ += fz * str * deltaTime;
                break;
              }
              case 1: { // wind
                velX += fx * str * deltaTime;
                velY += fy * str * deltaTime;
                velZ += fz * str * deltaTime;
                break;
              }
              case 2: { // turbulence
                var nx = Math.sin(posX * freq + totalTime * 1.3) * Math.cos(posZ * freq + totalTime * 0.7);
                var ny = Math.sin(posY * freq + totalTime * 0.9) * Math.cos(posX * freq + totalTime * 1.1);
                var nz = Math.sin(posZ * freq + totalTime * 1.7) * Math.cos(posY * freq + totalTime * 0.5);
                velX += nx * str * deltaTime;
                velY += ny * str * deltaTime;
                velZ += nz * str * deltaTime;
                break;
              }
              case 3: { // orbit
                var dx = posX;
                var dz = posZ;
                var dist = Math.max(Math.sqrt(dx * dx + dz * dz), 0.001);
                velX += (-dz / dist) * str * deltaTime;
                velZ += (dx / dist) * str * deltaTime;
                break;
              }
              case 4: { // drag
                velX += -velX * str * deltaTime;
                velY += -velY * str * deltaTime;
                velZ += -velZ * str * deltaTime;
                break;
              }
              case 5: { // radial / eject
                var rx = posX;
                var ry = posY;
                var rz = posZ;
                var biasLen = Math.sqrt(fx * fx + fy * fy + fz * fz);
                if (biasLen > 0.001) {
                  var radialLen = Math.max(Math.sqrt(rx * rx + ry * ry + rz * rz), 1);
                  rx += (fx / biasLen) * radialLen * 0.35;
                  ry += (fy / biasLen) * radialLen * 0.35;
                  rz += (fz / biasLen) * radialLen * 0.35;
                }
                var rdist = Math.max(Math.sqrt(rx * rx + ry * ry + rz * rz), 0.001);
                velX += (rx / rdist) * str * deltaTime;
                velY += (ry / rdist) * str * deltaTime;
                velZ += (rz / rdist) * str * deltaTime;
                break;
              }
            }
          }

          // Integrate position.
          posX += velX * deltaTime;
          posY += velY * deltaTime;
          posZ += velZ * deltaTime;

          if (emitterConfig.once && emitterConfig.bounds > 0 && Math.sqrt(posX * posX + posY * posY + posZ * posZ) > emitterConfig.bounds) {
            makeFinished(particles.subarray(base, base + 8));
            writeDormantOutput(i);
            continue;
          }

          // Write state back.
          particles[base] = posX;
          particles[base + 1] = posY;
          particles[base + 2] = posZ;
          particles[base + 3] = velX;
          particles[base + 4] = velY;
          particles[base + 5] = velZ;
          particles[base + 6] = age;
          particles[base + 7] = lifetime;

          // Compute interpolation t.
          var t = lifetime > 0 ? Math.min(1, Math.max(0, age / lifetime)) : 0;

          // Write render output.
          positions[i * 3] = posX;
          positions[i * 3 + 1] = posY;
          positions[i * 3 + 2] = posZ;
          sizes[i] = materialConfig.sizeStart + (materialConfig.sizeEnd - materialConfig.sizeStart) * t;
          colors[i * 3] = materialConfig.colorStart[0] + (materialConfig.colorEnd[0] - materialConfig.colorStart[0]) * t;
          colors[i * 3 + 1] = materialConfig.colorStart[1] + (materialConfig.colorEnd[1] - materialConfig.colorStart[1]) * t;
          colors[i * 3 + 2] = materialConfig.colorStart[2] + (materialConfig.colorEnd[2] - materialConfig.colorStart[2]) * t;
          opacities[i] = (materialConfig.opacityStart + (materialConfig.opacityEnd - materialConfig.opacityStart) * t) * particleEnvelope(t);
        }
      },

      dispose: function() {
        particles = null;
        positions = null;
        sizes = null;
        colors = null;
        opacities = null;
      },
    };
  }

  // --- Factory ---
  // Creates either a GPU compute system (when WebGPU device is available) or
  // a CPU fallback that feeds into the existing Points/WebGL2 renderer.

  function createSceneParticleSystem(device, entry) {
    if (device) {
      return createSceneComputeParticleSystem(device, entry);
    }
    return createSceneCPUParticleSystem(entry);
  }

  function sceneComputeSystemSignature(entry) {
    var emitter = entry && entry.emitter && typeof entry.emitter === "object" ? entry.emitter : {};
    return JSON.stringify({
      count: Math.max(0, Math.floor(sceneNumber(entry && entry.count, 0))),
      emitter: {
        kind: String(emitter.kind || ""),
        radius: sceneNumber(emitter.radius, 0),
        rate: sceneNumber(emitter.rate, 0),
        lifetime: sceneNumber(emitter.lifetime, 0),
        arms: Math.max(1, Math.floor(sceneNumber(emitter.arms, 2))),
        wind: sceneNumber(emitter.wind, 0),
        scatter: sceneNumber(emitter.scatter, 0),
        bounds: sceneNumber(entry && entry.bounds, 0),
        once: emitter.once === true,
      },
      forces: Array.isArray(entry && entry.forces) ? entry.forces : [],
      forceRegistryVersion: sceneParticleForceRegistryVersion,
      // Include payload kernel identity so a changed kernel triggers recreation.
      computeWGSL: (typeof entry.computeWGSL === "string") ? entry.computeWGSL : "",
      computeEntry: (typeof entry.computeEntry === "string") ? entry.computeEntry : "",
    });
  }

  // -----------------------------------------------------------------------
  // GPU Instanced Cull System
  // -----------------------------------------------------------------------
  // Creates the per-InstancedMesh GPU buffers, bind group, and compute
  // pipeline for frustum culling. Mirrors the native render/bundle/cull.go
  // architecture: inputBuf (80B InstanceRecords) → compute → outputBuf +
  // drawArgsBuf (indirect draw args). Capacity grows geometrically, never
  // shrinks.
  //
  // CRITICAL (D3): not-ready → DRAW-ALL (the 6-buffer direct pass.draw path),
  // NOT skip. Skipping produces invisible instances. The caller (draw site in
  // 16a) checks isReady() before branching — this system's update() is a
  // no-op when not ready.
  //
  // CRITICAL (Risk #1 guard): drawArgsBuf is reset EVERY frame BEFORE the
  // compute dispatch — writeBuffer([vertexCount,0,0,0]) clears instanceCount
  // so each frame starts from zero visible. Omitting this causes instanceCount
  // to accumulate across frames.
  //
  // Binding contract (mirrors native cull.go:33-36):
  //   @group(0) @binding(0) — CullUniforms (uniform, 112B)
  //   @group(0) @binding(1) — input InstanceRecords (read-only-storage)
  //   @group(0) @binding(2) — output InstanceRecords (storage, also vertex)
  //   @group(0) @binding(3) — drawArgs [u32; 4] (storage+indirect)

  var INSTANCED_CULL_RECORD_STRIDE = 80; // mat4(64) + pickData uint32x4(16)
  var INSTANCED_CULL_UNIFORM_SIZE  = 112; // 6 vec4 planes(96) + vertexCount u32 + radius f32 + 8B pad

  // SCENE_INSTANCED_CULL_BUILTIN_WGSL is the renderer's own frustum-cull
  // kernel. It mirrors cullWGSL in render/bundle/cull.go term for term, and it
  // scales the bounding radius PER INSTANCE by the largest of the three
  // upper-left column lengths of the instance transform.
  //
  // The scale term is a correctness requirement, not a tuning knob. A constant
  // radius drops an instance that its transform scales up, so the instance
  // disappears while it is plainly on screen. The largest column length never
  // under-estimates the sphere, so an instance is never wrongly culled. Shear
  // inflates the radius, which is safe.
  //
  // Cost: three length() calls and two comparisons per thread.
  //
  // The thread guard bounds on the LIVE instance count, not on arrayLength. The
  // input buffer's capacity runs 25% past the instance count, and WebGPU
  // zero-initializes a buffer, so a thread past the live count would read an
  // all-zero matrix. Its centre is the origin and its scale is zero, so it
  // passes the frustum test and compacts a degenerate instance into the output.
  // That instance rasterizes nothing, but it inflates the survivor count the
  // telemetry reports and it costs vertex shading.
  //
  // The live count rides in the uniform lane the native layout leaves as
  // padding. render/bundle/cull.go keeps that lane as padding, so this is a
  // documented divergence: an authored kernel that declares the field as
  // padding and ignores it is unaffected, and the binding size stays 112 bytes.
  var SCENE_INSTANCED_CULL_BUILTIN_WGSL = [
    "struct InstanceRecord {",
    "  model: mat4x4<f32>,",
    "  pick: vec4<u32>,",
    "};",
    "struct CullUniforms {",
    "  planes: array<vec4<f32>, 6>,",
    "  vertexCount: u32,",
    "  radius: f32,",
    "  instanceCount: u32,",
    "  _pad1: u32,",
    "};",
    "@group(0) @binding(0) var<uniform> cull: CullUniforms;",
    "@group(0) @binding(1) var<storage, read> src: array<InstanceRecord>;",
    "@group(0) @binding(2) var<storage, read_write> dst: array<InstanceRecord>;",
    "@group(0) @binding(3) var<storage, read_write> drawArgs: array<atomic<u32>, 4>;",
    "",
    "@compute @workgroup_size(64)",
    "fn main(@builtin(global_invocation_id) gid: vec3<u32>) {",
    "  let index = gid.x;",
    "  if (index >= min(cull.instanceCount, arrayLength(&src))) { return; }",
    "  let m = src[index].model;",
    "  let centre = m[3].xyz;",
    "  let scale = max(length(m[0].xyz), max(length(m[1].xyz), length(m[2].xyz)));",
    "  var radius = cull.radius;",
    "  if (scale > 0.0) { radius = radius * scale; }",
    "  for (var p = 0u; p < 6u; p = p + 1u) {",
    "    let plane = cull.planes[p];",
    "    let d = dot(plane.xyz, centre) + plane.w;",
    "    if (d < -radius) { return; }",
    "  }",
    "  let slot = atomicAdd(&drawArgs[1], 1u);",
    "  dst[slot] = src[index];",
    "}",
  ].join("\n");

  // sceneInstanceColumnScale returns the largest of the three upper-left column
  // lengths of a column-major mat4 stored at `base` in `transforms`. It is the
  // CPU oracle for the GPU kernel's scale term, and it mirrors
  // instanceCullRadius in render/bundle/primitive.go.
  function sceneInstanceColumnScale(transforms, base) {
    if (!transforms || base < 0 || base + 11 >= transforms.length) return 0;
    var x0 = transforms[base + 0], y0 = transforms[base + 1], z0 = transforms[base + 2];
    var x1 = transforms[base + 4], y1 = transforms[base + 5], z1 = transforms[base + 6];
    var x2 = transforms[base + 8], y2 = transforms[base + 9], z2 = transforms[base + 10];
    var s0 = Math.sqrt(x0 * x0 + y0 * y0 + z0 * z0);
    var s1 = Math.sqrt(x1 * x1 + y1 * y1 + z1 * z1);
    var s2 = Math.sqrt(x2 * x2 + y2 * y2 + z2 * z2);
    return Math.max(s0, Math.max(s1, s2));
  }

  // sceneInstanceCullRadius scales one base radius by one instance transform.
  // A scale of zero or less keeps the base radius, so a degenerate transform
  // never collapses the sphere to nothing.
  function sceneInstanceCullRadius(baseRadius, transforms, base) {
    var scale = sceneInstanceColumnScale(transforms, base);
    if (!(scale > 0)) return baseRadius;
    return baseRadius * scale;
  }

  // sceneInstancedMaxTransformScale returns the largest per-instance scale in a
  // packed mat4 array. An author-supplied cull kernel may ignore scale
  // entirely, so the JS side inflates the uniform radius by this bound. The
  // result over-includes instances, which keeps the image right; it never
  // drops one.
  function sceneInstancedMaxTransformScale(transforms, count) {
    if (!transforms || !(count > 0)) return 1;
    var limit = Math.min(count, Math.floor(transforms.length / 16));
    var max = 0;
    for (var i = 0; i < limit; i++) {
      var scale = sceneInstanceColumnScale(transforms, i * 16);
      if (scale > max) max = scale;
    }
    return max > 0 ? max : 1;
  }

  // sceneInstanceTransformFingerprint folds a packed mat4 array into four
  // interleaved FNV-1a lanes. It allocates nothing and reads each float once.
  // The renderer skips the instance-record encode AND the queue.writeBuffer
  // when the fingerprint repeats, so a static 10 000-instance mesh stops
  // re-uploading 800 KB every frame.
  //
  // Four lanes instead of one: a single 32-bit lane collides often on float
  // data that differs in one component. Four lanes over interleaved strides
  // make an undetected change far less likely, and they cost the same pass.
  function sceneInstanceTransformFingerprint(transforms, count) {
    if (!transforms || !(count > 0)) return "0:0:0:0:0";
    var limit = Math.min(count * 16, transforms.length);
    var view = _sceneFingerprintView(transforms, limit);
    var h0 = 2166136261, h1 = 2166136261, h2 = 2166136261, h3 = 2166136261;
    for (var i = 0; i < limit; i++) {
      var bits = view[i];
      h0 = (h0 ^ (bits & 0xff)) * 16777619;
      h1 = (h1 ^ ((bits >>> 8) & 0xff)) * 16777619;
      h2 = (h2 ^ ((bits >>> 16) & 0xff)) * 16777619;
      h3 = (h3 ^ (bits >>> 24)) * 16777619;
      h0 = h0 >>> 0; h1 = h1 >>> 0; h2 = h2 >>> 0; h3 = h3 >>> 0;
    }
    return limit + ":" + h0 + ":" + h1 + ":" + h2 + ":" + h3;
  }

  var _sceneFingerprintScratch = null;

  // _sceneFingerprintView exposes the raw bits of the float data as u32 without
  // copying when the source is a Float32Array. A plain Array falls back to a
  // reused scratch buffer, so the walk still allocates nothing per frame.
  function _sceneFingerprintView(transforms, limit) {
    if (transforms instanceof Float32Array) {
      return new Uint32Array(transforms.buffer, transforms.byteOffset, Math.min(limit, transforms.length));
    }
    if (!_sceneFingerprintScratch || _sceneFingerprintScratch.f32.length < limit) {
      var buffer = new ArrayBuffer(Math.max(64, limit) * 4);
      _sceneFingerprintScratch = { f32: new Float32Array(buffer), u32: new Uint32Array(buffer) };
    }
    for (var i = 0; i < limit; i++) _sceneFingerprintScratch.f32[i] = transforms[i];
    return _sceneFingerprintScratch.u32;
  }

  // scenePlaneFingerprint folds the six frustum planes the same way. The cull
  // dispatch may be skipped only when BOTH the transforms and the planes
  // repeat, because a moving camera changes the survivor set on its own.
  function scenePlaneFingerprint(planes) {
    if (!planes || planes.length < 6) return "";
    var out = "";
    for (var p = 0; p < 6; p++) {
      var plane = planes[p];
      if (!plane) return "";
      out += plane[0] + "," + plane[1] + "," + plane[2] + "," + plane[3] + ";";
    }
    return out;
  }

  // Scratch buffers shared by every cull system. update() runs once per mesh per
  // frame, and it finishes with the data before it returns, so one shared
  // allocation is safe and it removes two per-mesh allocations per frame.
  var _cullResetScratch = new Uint32Array(4);
  var _cullUniformBytes = new ArrayBuffer(INSTANCED_CULL_UNIFORM_SIZE);
  var _cullUniformF = new Float32Array(_cullUniformBytes);
  var _cullUniformU = new Uint32Array(_cullUniformBytes);

  function createSceneInstancedCullSystem(device, mesh, options) {
    var createOptions = options || {};
    // Validate and extract cull parameters from the mesh entry.
    var authoredWGSL = (typeof mesh.cullKernelWGSL === "string" && mesh.cullKernelWGSL.trim()) ? mesh.cullKernelWGSL : null;
    // A mesh without an authored kernel still gets GPU culling: the built-in
    // kernel above covers the plain frustum case and scales the radius per
    // instance. An authored kernel wins, because it may cull on rules the
    // renderer cannot see.
    var cullWGSL = authoredWGSL || SCENE_INSTANCED_CULL_BUILTIN_WGSL;
    var usesBuiltinKernel = !authoredWGSL;
    var entryPoint = (!usesBuiltinKernel && typeof mesh.cullKernelEntry === "string" && mesh.cullKernelEntry.trim()) ? mesh.cullKernelEntry : "main";
    // Radius resolution order: the authored cullRadius, then the caller's
    // geometry-derived bound, then 2.0. The 2.0 tail is a last resort and it
    // under-estimates a large primitive, so 16a always supplies
    // options.fallbackRadius from the real local bounds.
    var cullRadius = (typeof mesh.cullRadius === "number" && mesh.cullRadius > 0)
      ? mesh.cullRadius
      : (sceneNumber(createOptions.fallbackRadius, 0) > 0 ? sceneNumber(createOptions.fallbackRadius, 0) : 2.0);
    // Constrain cullBackend to known values.
    var cullBackend = (typeof mesh.cullBackend === "string" && mesh.cullBackend.trim()) ? mesh.cullBackend.trim().toLowerCase() : "webgpu";
    if (cullBackend !== "webgpu") cullBackend = "webgpu";

    if (!cullWGSL) return null;

    // Instanced count is serialized as `count` (legacyProps); `instanceCount`
    // is often absent. Resolve instanceCount→count→0 so the cull buffer is
    // sized for the real instance count, not 1.
    var instanceCount = sceneNumber(mesh.instanceCount, sceneNumber(mesh.count, 0));
    if (instanceCount <= 0) instanceCount = 1;
    var capacity = Math.max(32, instanceCount + Math.floor(instanceCount / 4));

    var disposed = false;
    var ready = false;
    var computePipeline = null;
    var bindGroup = null;
    // Static-scene skip state. uploadedOnce guards the very first frame: the
    // input buffer holds nothing until one upload lands, so no skip may happen
    // before it.
    var uploadedOnce = false;
    var lastTransformFingerprint = null;
    var lastPlaneKey = "";
    var lastUniformVertexCount = -1;
    var lastUniformRadius = -1;
    var lastDispatchInstanceCount = -1;

    var bufBytes = capacity * INSTANCED_CULL_RECORD_STRIDE;

    var inputBuf = device.createBuffer({
      size: bufBytes,
      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
      label: "gosx.cull.input",
    });
    var outputBuf = device.createBuffer({
      // STORAGE for compute write + VERTEX for the main draw pass.
      size: bufBytes,
      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.VERTEX | GPUBufferUsage.COPY_DST,
      label: "gosx.cull.output",
    });
    var drawArgsBuf = device.createBuffer({
      // STORAGE for atomicAdd in the shader + INDIRECT for drawIndirect +
      // COPY_SRC so we can blit to the staging buffer for survivor readback.
      size: 16,
      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.INDIRECT | GPUBufferUsage.COPY_DST | GPUBufferUsage.COPY_SRC,
      label: "gosx.cull.drawArgs",
    });

    // Staging buffer for CPU-side survivor readback (telemetry only).
    // 16 bytes = [vertexCount, instanceCount, firstVertex, firstInstance].
    var stagingBuf = device.createBuffer({
      size: 16,
      usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST,
      label: "gosx.cull.staging",
    });
    var stagingMapping = false; // guard against overlapping mapAsync calls
    var cullUniformBuf = device.createBuffer({
      size: INSTANCED_CULL_UNIFORM_SIZE,
      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
      label: "gosx.cull.uniform",
    });

    var bindGroupLayout = device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: GPUShaderStage.COMPUTE, buffer: { type: "uniform"            } },
        { binding: 1, visibility: GPUShaderStage.COMPUTE, buffer: { type: "read-only-storage"  } },
        { binding: 2, visibility: GPUShaderStage.COMPUTE, buffer: { type: "storage"            } },
        { binding: 3, visibility: GPUShaderStage.COMPUTE, buffer: { type: "storage"            } },
      ],
    });
    var pipelineLayout = device.createPipelineLayout({ bindGroupLayouts: [bindGroupLayout] });

    function markReady(pipeline) {
      if (disposed) return;
      computePipeline = pipeline;
      bindGroup = device.createBindGroup({
        layout: bindGroupLayout,
        entries: [
          { binding: 0, resource: { buffer: cullUniformBuf, size: INSTANCED_CULL_UNIFORM_SIZE } },
          { binding: 1, resource: { buffer: inputBuf,       size: bufBytes                    } },
          { binding: 2, resource: { buffer: outputBuf,      size: bufBytes                    } },
          { binding: 3, resource: { buffer: drawArgsBuf,    size: 16                          } },
        ],
      });
      ready = true;
    }

    // Async-validate-with-fallback: validate payload kernel. On failure, stay
    // not-ready (caller draws-all, D3). No builtin fallback kernel exists for
    // the cull path — the kernel is always payload-provided (from the mesh's
    // cullKernelWGSL; Elio produces this in the native dominance pass).
    var scopedDevice = device;
    try {
      scopedDevice.pushErrorScope("validation");
    } catch (_err) {
      // pushErrorScope not supported — proceed without scope guard.
      scopedDevice.createComputePipelineAsync({
        layout: pipelineLayout,
        compute: { module: device.createShaderModule({ code: cullWGSL }), entryPoint: entryPoint },
      }).then(markReady).catch(function(err) {
        if (!disposed) console.warn("[gosx] gpu-cull: kernel pipeline creation failed:", err);
      });
      scopedDevice = null;
    }
    if (scopedDevice) {
      scopedDevice.createComputePipelineAsync({
        layout: pipelineLayout,
        compute: { module: device.createShaderModule({ code: cullWGSL }), entryPoint: entryPoint },
      }).then(function(pipeline) {
        return sceneComputePopErrorScope(scopedDevice).then(function(scopeErr) {
          if (disposed) return;
          if (scopeErr) {
            console.warn("[gosx] gpu-cull: kernel validation error for mesh '" + (mesh.id || "?") + "':", scopeErr);
            // Stay not-ready — caller draws-all.
          } else {
            markReady(pipeline);
          }
        });
      }).catch(function(err) {
        return sceneComputePopErrorScope(scopedDevice).then(function() {
          if (!disposed) console.warn("[gosx] gpu-cull: kernel pipeline rejected for mesh '" + (mesh.id || "?") + "':", err);
        });
      });
    }

    return {
      inputBuf: inputBuf,
      outputBuf: outputBuf,
      drawArgsBuf: drawArgsBuf,
      cullUniformBuf: cullUniformBuf,
      capacity: capacity,
      cullRadius: cullRadius,
      instanceCount: instanceCount,
      usesBuiltinKernel: usesBuiltinKernel,
      lastSurvivors: null,  // null until first successful poll; then a number
      lastVertexCount: 0,
      // dispatchCount / skippedDispatchCount feed the renderer diagnostics so a
      // page can prove the static-scene skip fired.
      dispatchCount: 0,
      skippedDispatchCount: 0,

      isReady: function() { return ready; },

      // requestSurvivorReadback copies drawArgsBuf into the staging buffer so
      // pollSurvivors() can read it back on the CPU. Call once per encoder,
      // AFTER the compute dispatch (i.e. after update()). Zero overhead when
      // not called — the copy is only inserted when this method is invoked.
      requestSurvivorReadback: function(encoder) {
        if (!ready || disposed) return;
        encoder.copyBufferToBuffer(drawArgsBuf, 0, stagingBuf, 0, 16);
      },

      // pollSurvivors() asynchronously maps the staging buffer and stores the
      // survivor count. A mapping flag prevents overlapping mapAsync calls.
      // Returns without error if a map is already in flight.
      pollSurvivors: function() {
        var self = this;
        if (!ready || disposed || stagingMapping) return;
        stagingMapping = true;
        stagingBuf.mapAsync(GPUMapMode.READ).then(function() {
          if (disposed) { stagingMapping = false; return; }
          try {
            var arr = new Uint32Array(stagingBuf.getMappedRange(0, 16));
            self.lastVertexCount = arr[0];
            self.lastSurvivors   = arr[1];
          } finally {
            stagingBuf.unmap();
            stagingMapping = false;
          }
        }).catch(function() {
          stagingMapping = false;
        });
      },

      // update() is called once per frame, before the main pass.
      // planes: [6][4] float array — [nx,ny,nz,d] per plane.
      // vertexCount: geometry primitive vertex count.
      // instanceRecords: Float32Array of 80B InstanceRecord data (mat4 + pickData),
      //   or null when the caller knows the input buffer already holds them.
      // instanceCount: number of active instances.
      // options.transformFingerprint: fold of the source transforms. When it
      //   repeats AND the frustum planes repeat, update() skips the reset, the
      //   upload and the dispatch. outputBuf and drawArgsBuf keep the previous
      //   frame's contents, so the caller's drawIndirect still draws the right
      //   survivors. Pass null to force work every frame.
      // options.maxInstanceScale: largest per-instance scale in the transforms.
      //   The built-in kernel scales per thread and ignores this. An authored
      //   kernel may ignore scale, so the uniform radius carries the bound.
      // Returns true when the dispatch was encoded, false when it was skipped.
      update: function(device, encoder, planes, vertexCount, instanceRecords, instanceCount, options) {
        if (!ready) return false;
        var opts = options || {};
        var fingerprint = typeof opts.transformFingerprint === "string" ? opts.transformFingerprint : null;
        var planeKey = scenePlaneFingerprint(planes);
        var radiusScale = usesBuiltinKernel
          ? 1
          : Math.max(1, sceneNumber(opts.maxInstanceScale, 1));
        var effectiveRadius = cullRadius * radiusScale;

        if (
          uploadedOnce &&
          fingerprint !== null &&
          fingerprint === lastTransformFingerprint &&
          planeKey !== "" &&
          planeKey === lastPlaneKey &&
          vertexCount === lastUniformVertexCount &&
          effectiveRadius === lastUniformRadius &&
          instanceCount === lastDispatchInstanceCount
        ) {
          this.skippedDispatchCount += 1;
          return false;
        }

        // CRITICAL (Risk #1): reset drawArgs EVERY frame before dispatch.
        // drawArgs[1] = instanceCount accumulates via atomicAdd in the shader;
        // if not reset each frame it compounds across frames.
        _cullResetScratch[0] = vertexCount;
        device.queue.writeBuffer(drawArgsBuf, 0, _cullResetScratch);

        // Upload instance records.
        if (instanceRecords && instanceRecords.byteLength > 0) {
          device.queue.writeBuffer(inputBuf, 0, instanceRecords);
          uploadedOnce = true;
        }

        // Upload cull uniforms: 6 planes (6*16=96B) + vertexCount u32 + radius f32 + 8B pad.
        var uf = _cullUniformF;
        var uu = _cullUniformU;
        for (var p = 0; p < 6; p++) {
          uf[p * 4 + 0] = planes[p][0]; // nx
          uf[p * 4 + 1] = planes[p][1]; // ny
          uf[p * 4 + 2] = planes[p][2]; // nz
          uf[p * 4 + 3] = planes[p][3]; // d
        }
        uu[24] = vertexCount;      // offset 96 = index 24 in u32 view
        uf[25] = effectiveRadius;  // offset 100 = index 25 in f32 view
        // Offset 104 is padding in the native layout. The built-in kernel reads
        // the live instance count from it so a thread past the count cannot
        // compact a zero-filled record. An authored kernel ignores it.
        uu[26] = Math.max(0, Math.floor(instanceCount));
        uu[27] = 0;
        device.queue.writeBuffer(cullUniformBuf, 0, _cullUniformBytes);

        // Dispatch the cull compute pass.
        var pass = encoder.beginComputePass();
        pass.setPipeline(computePipeline);
        pass.setBindGroup(0, bindGroup);
        pass.dispatchWorkgroups(Math.ceil(Math.max(1, instanceCount) / 64));
        pass.end();

        lastTransformFingerprint = fingerprint;
        lastPlaneKey = planeKey;
        lastUniformVertexCount = vertexCount;
        lastUniformRadius = effectiveRadius;
        lastDispatchInstanceCount = instanceCount;
        this.dispatchCount += 1;
        return true;
      },

      dispose: function() {
        disposed = true;
        if (inputBuf)      inputBuf.destroy();
        if (outputBuf)     outputBuf.destroy();
        if (drawArgsBuf)   drawArgsBuf.destroy();
        if (cullUniformBuf) cullUniformBuf.destroy();
        if (stagingBuf)    stagingBuf.destroy();
        computePipeline = null;
        bindGroup = null;
        ready = false;
      },
    };
  }

  // cullSystemSignature returns a string key for the cull system. The system
  // is recreated when the kernel WGSL, entry point, radius, or capacity changes.
  function cullSystemSignature(mesh) {
    return JSON.stringify({
      cullKernelWGSL:  (typeof mesh.cullKernelWGSL  === "string") ? mesh.cullKernelWGSL  : "",
      cullKernelEntry: (typeof mesh.cullKernelEntry  === "string") ? mesh.cullKernelEntry  : "",
      cullRadius:      (typeof mesh.cullRadius       === "number") ? mesh.cullRadius       : 0,
      instanceCount:   sceneNumber(mesh.instanceCount, sceneNumber(mesh.count, 0)),
    });
  }

  if (typeof window !== "undefined" && window.__gosx_scene3d_api) {
    Object.assign(window.__gosx_scene3d_api, {
      createSceneParticleSystem,
      createSceneInstancedCullSystem,
      cullSystemSignature,
      SCENE_INSTANCED_CULL_BUILTIN_WGSL,
      sceneInstanceColumnScale,
      sceneInstanceCullRadius,
      sceneInstancedMaxTransformScale,
      sceneInstanceTransformFingerprint,
      scenePlaneFingerprint,
      listSceneParticleForces,
      registerSceneParticleForce,
      registerSceneParticleForceKind,
      sceneComputeSystemSignature,
      unregisterSceneParticleForce,
    });
  }
